1	import type { Session } from '@dailies/core';
2	import { classifyCommand, type CommandClass } from './commands';
3	
4	export type RunOutcome = 'pass' | 'fail' | 'unknown';
5	
6	export interface ToolRun {
7	  callEntryId: string;
8	  resultEntryId: string | null;
9	  index: number;
10	  command: string;
11	  cls: CommandClass;
12	  outcome: RunOutcome;
13	}
14	
15	const ANSI = /\x1b\[[0-9;]*[a-zA-Z]/g;
16	
17	function stripAnsi(text: string): string {
18	  return text.replace(ANSI, '');
19	}
20	
21	function parseTestOutcome(text: string): RunOutcome {
22	  for (const m of text.matchAll(/(\d+)\s+(?:failed|failing)/g)) {
23	    if (Number(m[1]) > 0) return 'fail';
24	  }
25	  if (/Tests?:\s+\d+\s+failed/.test(text)) return 'fail';
26	  if (/^FAIL\b/m.test(text)) return 'fail';
27	  if (/AssertionError/.test(text)) return 'fail';
28	
29	  if (/\d+\s+passed/.test(text)) return 'pass';
30	  if (/^PASS\b/m.test(text)) return 'pass';
31	  if (/^ok\s+\S/m.test(text)) return 'pass';
32	  if (/test result: ok/.test(text)) return 'pass';
33	
34	  return 'unknown';
35	}
36	
37	// A pipe, a `;`, or a newline (bash chains statements on one exactly as it does on the other)
38	// reports the exit status of its last part, not the part that was actually classified; `||` is
39	// two `|` characters, so testing for `|` alone already covers it. A backgrounded command (`&`,
40	// not `&&`) reports the shell having started the job, never the job's own outcome, so it is just
41	// as untrustworthy; `&&` is excluded first so a chain that merely contains that token is not
42	// flagged by the lone-`&` check.
43	const UNTRUSTED_EXIT = /[|;\n\r]/;
44	
45	function hasUntrustedExit(command: string): boolean {
46	  return UNTRUSTED_EXIT.test(command) || command.replace(/&&/g, '').includes('&');
47	}
48	
49	function parseTypecheckOutcome(text: string, exitTrusted: boolean): RunOutcome {
50	  if (/error TS\d+/.test(text)) return 'fail';
51	  if (/Found [1-9]\d*\s+errors?/.test(text)) return 'fail';
52	  if (/Found 0 errors/.test(text)) return 'pass';
53	  if (text.trim() === '') return 'pass';
54	  if (exitTrusted) return 'pass';
55	  return 'unknown';
56	}
57	
58	function parseLintOrBuildOutcome(text: string, exitTrusted: boolean): RunOutcome {
59	  if (/[1-9]\d*\s+errors?/.test(text)) return 'fail';
60	  if (/[1-9]\d*\s+problems?/.test(text)) return 'fail';
61	  if (text.trim() === '') return 'pass';
62	  if (/compiled successfully/.test(text)) return 'pass';
63	  if (/built in/.test(text)) return 'pass';
64	  if (/Done in/.test(text)) return 'pass';
65	  if (/0 errors/.test(text)) return 'pass';
66	  if (/0 problems/.test(text)) return 'pass';
67	  if (exitTrusted) return 'pass';
68	  return 'unknown';
69	}
70	
71	export function parseOutcome(cls: CommandClass, output: string, isError: boolean, o?: { exitTrusted?: boolean }): RunOutcome {
72	  if (isError) return 'fail';
73	  const text = stripAnsi(output);
74	  if (cls === 'test') return parseTestOutcome(text);
75	  const exitTrusted = o?.exitTrusted ?? false;
76	  if (cls === 'typecheck') return parseTypecheckOutcome(text, exitTrusted);
77	  return parseLintOrBuildOutcome(text, exitTrusted);
78	}
79	
80	export function collectRuns(session: Session): ToolRun[] {
81	  const runs: ToolRun[] = [];
82	  for (const call of session.entries) {
83	    if (call.kind !== 'tool_call' || !call.command || call.toolUseId === undefined) continue;
84	    const cls = classifyCommand(call.command);
85	    if (cls === 'other') continue;
86	    const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
87	    const exitTrusted = !hasUntrustedExit(call.command);
88	    const outcome: RunOutcome = result ? parseOutcome(cls, result.text, result.isError ?? false, { exitTrusted }) : 'unknown';
89	    runs.push({
90	      callEntryId: call.id,
91	      resultEntryId: result?.id ?? null,
92	      index: call.index,
93	      command: call.command,
94	      cls,
95	      outcome,
96	    });
97	  }
98	  return runs;
99	}
100	
101	const HEADLINE_MAX_CHARS = 24;
102	const HEADLINE_FAIL = /(\d+)\s+(?:failed|failing)/g;
103	const HEADLINE_PASS = /(\d+)\s+passed/g;
104	const HEADLINE_ERROR = /(\d+)\s+(?:errors?|problems?)/g;
105	
106	/** The last match of `re` in `text` whose captured count is at least `minCount`, or null. */
107	function lastHeadlineMatch(re: RegExp, text: string, minCount: number): string | null {
108	  let found: string | null = null;
109	  for (const m of text.matchAll(re)) {
110	    if (Number(m[1]) >= minCount) found = m[0];
111	  }
112	  return found;
113	}
114	
115	function normalizeHeadline(fragment: string): string {
116	  return fragment.replace(/\s+/g, ' ').trim().slice(0, HEADLINE_MAX_CHARS);
117	}
118	
119	/** The decisive fragment of a run's output ("14 passed", "2 failed", "0 errors"), or null when nothing in it says so. */
120	export function headlineFor(cls: CommandClass, output: string): string | null {
121	  const text = stripAnsi(output);
122	  if (cls === 'test') {
123	    const failed = lastHeadlineMatch(HEADLINE_FAIL, text, 1);
124	    if (failed) return normalizeHeadline(failed);
125	    const passed = lastHeadlineMatch(HEADLINE_PASS, text, 0);
126	    return passed ? normalizeHeadline(passed) : null;
127	  }
128	  if (cls === 'typecheck' || cls === 'lint' || cls === 'build') {
129	    const errors = lastHeadlineMatch(HEADLINE_ERROR, text, 0);
130	    return errors ? normalizeHeadline(errors) : null;
131	  }
132	  return null;
133	}
