2	import { completeJson } from '@dailies/agent';
3	import { computeFacts, EvidenceRef, Storyboard, type Beat, type Claim, type Entry, type Facts, type IngestArtifact, type Line, type Scene, type Session } from '@dailies/core';
4	import { collectRuns, headlineFor, type ToolRun } from '@dailies/verify';
5	import { writerPrompt, type WriterMaterial } from '../prompts/writer';
6	import type { Stage } from '../types';
7	import { cut, knownCommits, patchCounts, repoLabel, resolveCommit, type EditArtifact } from './edit';
8	import type { StageDeps } from './index';
