11	export interface ScriptArtifact { storyboard: Storyboard; discarded: string[] }
12	
13	type SceneOf<T extends Scene['type']> = Extract<Scene, { type: T }>;
14	type Step = SceneOf<'terminal'>['steps'][number];
15	type FlaggedClaim = Claim & { verdict: 'contradicted' | 'stale' };
16	
17	const TARGET_SEC = 75;
18	const MAX_FLAGS = 3;
19	const SPOKEN_QUOTE_CHARS = 120;
20	const MAX_LINES_TOTAL = 11;
21	const MAX_WORDS_PER_LINE = 18;
22	const MAX_TERMINAL_SCENES = 2;
23	const MAX_DIFF_SCENES = 2;
24	// What the scene schema allows on screen.
25	const ON_SCREEN = { promptQuote: 280, command: 200, output: 600, hunk: 2400, steps: 4, statValue: 16, flagQuote: 240, flagReality: 200 };
26	// What the writer is shown of each beat.
27	const MATERIAL = { entries: 24, entriesFromStart: 8, entryChars: 400, patches: 3, patchChars: 1500, claims: 12, quoteChars: 200, feedbackChars: 2000 };
28	
29	const STATS: [key: string, label: string][] = [
30	  ['sessions.count', 'Sessions'],
31	  ['commits.count', 'Commits'],
32	  ['files.count', 'Files touched'],
33	  ['turns.total', 'Turns'],
34	  ['tools.calls', 'Tool calls'],
35	  ['duration.minutes', 'Minutes'],
36	];
