38	const flat = (text: string) => text.replace(/\s+/g, ' ').trim();
39	const endsSentence = (text: string) => /[.!?]$/.test(text);
40	
41	/** `cut`, ending on a whole word where there is one to end on. */
42	function cutAtWord(text: string, max: number): string {
43	  if (text.length <= max) return text;
44	  const head = text.slice(0, max - 1);
45	  const space = head.lastIndexOf(' ');
46	  return `${(space > max / 2 ? head.slice(0, space) : head).trimEnd()}…`;
47	}
48	
49	/** The last `max` characters, starting on a line where one starts early enough: a run's summary is at its end. */
50	function tail(text: string, max: number): string {
51	  const trimmed = text.trimEnd();
52	  if (trimmed.length <= max) return trimmed;
53	  const end = trimmed.slice(trimmed.length - (max - 1));
54	  const lineStart = end.indexOf('\n') + 1;
55	  return `…${lineStart > 0 && lineStart < end.length / 2 ? end.slice(lineStart) : end}`;
56	}
57	
58	function day(iso: string): string {
59	  const ms = Date.parse(iso);
60	  return Number.isNaN(ms) ? cut(flat(iso), 24) : new Date(ms).toISOString().slice(0, 10);
61	}
62	
63	function realityOf(claim: FlaggedClaim): string {
64	  if (claim.verdict === 'stale') return 'Code was edited after the last passing run.';
65	  if (claim.kind === 'tests_pass') return 'The last test run before that message had failed.';
66	  const reason = flat(claim.reason ?? '') || 'the record contradicts this claim';
67	  return cut(`${reason[0]!.toUpperCase()}${reason.slice(1)}${endsSentence(reason) ? '' : '.'}`, ON_SCREEN.flagReality);
68	}
69	
70	/**
71	 * The flag scene for a claim a rule found contradicted or stale. Every word of it is the agent's own quote,
72	 * a fixed sentence, or the rule's reason: no model writes any part of a flag.
73	 */
74	export function flagScene(claim: FlaggedClaim): SceneOf<'flag'> {
75	  const quote = flat(claim.quote);
76	  const spoken = cutAtWord(quote, SPOKEN_QUOTE_CHARS);
77	  const reality = realityOf(claim);
78	  return {
79	    id: `flag_${claim.id}`,
80	    type: 'flag',
81	    claimId: claim.id,
82	    verdict: claim.verdict,
83	    quote: cut(quote, ON_SCREEN.flagQuote),
84	    reality,
85	    lines: [
86	      // What the agent wrote rests on the entry that holds the words; what the record shows rests on what the rule found.
87	      { id: `flag_${claim.id}_quote`, text: `The agent wrote: "${spoken}"${endsSentence(spoken) ? '' : '.'}`, evidence: [{ type: 'entry', entryId: claim.entryId, quote: claim.quote }] },
88	      { id: `flag_${claim.id}_reality`, text: reality, evidence: claim.evidence },
89	    ],
90	  };
91	}
92	
93	const isFlagged = (claim: Claim): claim is FlaggedClaim => (claim.verdict === 'contradicted' || claim.verdict === 'stale') && claim.evidence.length > 0;
94	
95	// The writer points and narrates; it supplies none of what a scene shows. Keys other than these are ignored.
96	const WriterReply = z.object({ scenes: z.array(z.unknown()) });
97	const WriterLine = z.object({ text: z.string().trim().min(1).max(220), evidence: z.array(EvidenceRef).min(1) });
98	const rawLines = z.array(z.unknown());
99	const WriterScene = z.discriminatedUnion('type', [
100	  z.object({ type: z.literal('prompt'), entryId: z.string(), lines: rawLines }),
101	  z.object({ type: z.literal('terminal'), steps: z.array(z.object({ entryId: z.string() })).min(1), lines: rawLines }),
102	  z.object({ type: z.literal('diff'), sha: z.string(), path: z.string(), lines: rawLines }),
103	  z.object({ type: z.literal('stats'), lines: rawLines }),
104	]);
105	type WriterScene = z.infer<typeof WriterScene>;
106	
107	function typeName(raw: unknown): string {
108	  const type = typeof raw === 'object' && raw !== null && 'type' in raw ? raw.type : undefined;
109	  return typeof type === 'string' ? cut(flat(type), 20) : 'untyped';
110	}
111	
112	const wordCount = (text: string): number => text.trim().split(/\s+/).filter(Boolean).length;
113	
114	/**
115	 * The hard limits the writer is told about but code enforces regardless: a line over the word
116	 * limit is dropped outright; a terminal or diff scene past the per-type cap is dropped whole,
117	 * earliest kept; the remaining lines are then capped at the total, dropped from the end across
118	 * the whole sequence. A scene left with no lines is removed.
119	 */
120	function applyHardLimits(scenes: Scene[], discarded: string[]): Scene[] {
121	  const byWordLimit = scenes.flatMap((scene) => {
122	    const lines = scene.lines.filter((line) => {
123	      const words = wordCount(line.text);
124	      if (words <= MAX_WORDS_PER_LINE) return true;
125	      discarded.push(`${scene.id}: a line of ${words} words is over the ${MAX_WORDS_PER_LINE}-word limit`);
126	      return false;
127	    });
128	    if (lines.length === 0) {
129	      discarded.push(`${scene.id}: left with no lines after the ${MAX_WORDS_PER_LINE}-word limit`);
130	      return [];
131	    }
132	    return lines.length === scene.lines.length ? [scene] : [{ ...scene, lines } as Scene];
133	  });
134	
135	  let terminalSeen = 0;
136	  let diffSeen = 0;
137	  const byTypeCap = byWordLimit.filter((scene) => {
138	    if (scene.type === 'terminal' && (terminalSeen += 1) > MAX_TERMINAL_SCENES) {
139	      discarded.push(`${scene.id}: over the ${MAX_TERMINAL_SCENES}-terminal-scene limit`);
140	      return false;
141	    }
142	    if (scene.type === 'diff' && (diffSeen += 1) > MAX_DIFF_SCENES) {
143	      discarded.push(`${scene.id}: over the ${MAX_DIFF_SCENES}-diff-scene limit`);
144	      return false;
145	    }
146	    return true;
147	  });
148	
149	  let total = 0;
150	  const capped: Scene[] = [];
151	  for (const scene of byTypeCap) {
152	    if (total >= MAX_LINES_TOTAL) {
153	      discarded.push(`${scene.id}: dropped past the ${MAX_LINES_TOTAL}-line total`);
154	      continue;
155	    }
156	    const room = MAX_LINES_TOTAL - total;
157	    const lines = scene.lines.length <= room ? scene.lines : scene.lines.slice(0, room);
158	    if (lines.length < scene.lines.length) discarded.push(`${scene.id}: ${scene.lines.length - lines.length} line(s) dropped past the ${MAX_LINES_TOTAL}-line total`);
159	    total += lines.length;
160	    if (lines.length > 0) capped.push(lines.length === scene.lines.length ? scene : ({ ...scene, lines } as Scene));
161	  }
162	  return capped;
163	}
