165	export function scriptStage(deps: StageDeps): Stage<ScriptArtifact> {
166	  return {
167	    name: 'script',
168	    maxAttempts: 3,
169	    async run(ctx) {
170	      const ingest = ctx.read<IngestArtifact>('ingest');
171	      const { beats } = ctx.read<EditArtifact>('edit');
172	      const verify = ctx.read<VerifyArtifact>('verify');
173	
174	      const sessions = new Map(ingest.sessions.map((s) => [s.id, s]));
175	      const entries = new Map(ingest.sessions.flatMap((s) => s.entries.map((e) => [e.id, e] as const)));
176	      const commits = knownCommits(ingest);
177	      const facts = computeFacts(ingest.sessions);
178	      const repo = repoLabel(ctx.run.repoUrl);
179	      const windowLabel = [...new Set([day(ctx.run.since), day(ctx.run.until)])].join(' – ');
180	
181	      const runs = new Map<string, ToolRun[]>();
182	      const runsOf = (session: Session): ToolRun[] => {
183	        if (!runs.has(session.id)) runs.set(session.id, collectRuns(session));
184	        return runs.get(session.id)!;
185	      };
186	
187	      // Newest first: the later session, then the later entry.
188	      const startOf = (claim: Claim) => Date.parse(sessions.get(claim.sessionId)?.startedAt ?? '') || 0;
189	      const indexOf = (claim: Claim) => entries.get(claim.entryId)?.index ?? -1;
190	      const flagged = verify.claims
191	        .filter(isFlagged)
192	        .sort((a, b) => startOf(b) - startOf(a) || indexOf(b) - indexOf(a))
193	        .slice(0, MAX_FLAGS);
194	
195	      /** A shell call the record holds a readable result for, as a terminal step; null when there is nothing to show. */
196	      const stepFor = (entryId: string): Step | null => {
197	        const entry = entries.get(entryId);
198	        const session = entry && sessions.get(entry.sessionId);
199	        if (!entry || !session || entry.toolUseId === undefined) return null;
200	        const call = entry.kind === 'tool_call' ? entry : session.entries.find((e) => e.kind === 'tool_call' && e.toolUseId === entry.toolUseId);
201	        if (!call || call.command === undefined) return null;
202	        const result = session.entries.find((e) => e.kind === 'tool_result' && e.toolUseId === call.toolUseId);
203	        if (!result) return null;
204	        // A test, build, type-check or lint run gets its mark from the parsed output. One the parser cannot read gets no mark at all.
205	        const run = runsOf(session).find((r) => r.callEntryId === call.id);
206	        if (run?.outcome === 'unknown') return null;
207	        const ok = run ? run.outcome === 'pass' : !(result.isError ?? false);
208	        const headline = run ? headlineFor(run.cls, result.text) ?? undefined : undefined;
209	        return { command: cut(flat(call.command), ON_SCREEN.command), output: tail(result.text, ON_SCREEN.output), ok, entryId: call.id, headline };
210	      };
211	
212	      /** The scene the writer pointed at, filled from the record; or the reason there is nothing there to show. */
213	      const frame = (scene: WriterScene, id: string, lines: Line[]): Scene | string => {
214	        if (scene.type === 'prompt') {
215	          const entry = entries.get(scene.entryId);
216	          if (!entry || entry.kind !== 'user' || flat(entry.text) === '') return `${scene.entryId} is not a human prompt`;
217	          return { id, type: 'prompt', lines, quote: cut(flat(entry.text), ON_SCREEN.promptQuote), sessionId: entry.sessionId, entryId: entry.id };
218	        }
219	        if (scene.type === 'terminal') {
220	          const steps = scene.steps.flatMap((s) => stepFor(s.entryId) ?? []).slice(0, ON_SCREEN.steps);
221	          if (steps.length === 0) return 'no step points at a command with a readable result';
222	          return { id, type: 'terminal', lines, steps };
223	        }
224	        if (scene.type === 'diff') {
225	          const sha = resolveCommit(scene.sha, commits);
226	          const patch = sha === null ? undefined : ingest.diffs[`${sha}:${scene.path}`];
227	          const hunkAt = patch?.search(/^@@/m) ?? -1;
228	          if (sha === null || patch === undefined || hunkAt === -1) return 'no patch for that commit and path';
229	          return { id, type: 'diff', lines, sha, path: scene.path, hunk: cut(patch.slice(hunkAt), ON_SCREEN.hunk), ...patchCounts(patch) };
230	        }
231	        const items = STATS.filter(([key]) => Object.hasOwn(facts, key) && facts[key] !== 0).map(([key, label]) => ({
232	          label,
233	          value: cut(String(facts[key]), ON_SCREEN.statValue),
234	          statKey: key,
235	        }));
236	        return { id, type: 'stats', lines, items };
237	      };
238	
239	      const { system, user } = writerPrompt({
240	        repo,
241	        window: windowLabel,
242	        targetSec: TARGET_SEC,
243	        facts,
244	        beats: beats.map((beat) => beatMaterial(beat, ingest, sessions)),
245	        verified: verify.claims
246	          .filter((c) => c.verdict === 'verified')
247	          .slice(0, MATERIAL.claims)
248	          .map((c) => ({ kind: c.kind, quote: cut(flat(c.quote), MATERIAL.quoteChars), entryId: c.entryId })),
249	        flagged: flagged.map((c) => ({ quote: cut(flat(c.quote), MATERIAL.quoteChars), sessionId: c.sessionId })),
250	        feedback: ctx.feedback === null ? null : cut(ctx.feedback, MATERIAL.feedbackChars),
251	      });
252	      const reply = await completeJson({ client: deps.client, role: 'writer', name: 'writer', system, user, output: WriterReply });
253	
254	      const discarded: string[] = [];
255	      const written: Scene[] = [];
256	      let lineCount = 0;
257	      reply.scenes.forEach((raw, n) => {
258	        const where = `scene ${n + 1} (${typeName(raw)})`;
259	        const parsed = WriterScene.safeParse(raw);
260	        if (!parsed.success) return void discarded.push(`${where}: not a scene the writer may produce`);
261	        if (parsed.data.type === 'stats' && written.some((s) => s.type === 'stats')) return void discarded.push(`${where}: the reel closes on one stats scene`);
262	
263	        const kept = parsed.data.lines.flatMap((rawLine, k) => {
264	          const line = WriterLine.safeParse(rawLine);
265	          if (!line.success) discarded.push(`${where} line ${k + 1}: no text or no evidence`);
266	          return line.success ? [line.data] : [];
267	        });
268	        if (kept.length === 0) return void discarded.push(`${where}: no line with evidence`);
269	
270	        const scene = frame(parsed.data, `sc_${written.length + 1}`, kept.map((line) => ({ id: `l${(lineCount += 1)}`, ...line })));
271	        if (typeof scene === 'string') return void discarded.push(`${where}: ${scene}`);
272	        written.push(scene);
273	      });
274	      if (written.length === 0) throw new Error(`the writer returned no usable scene (${discarded.length} discarded)`);
275	
276	      const limited = applyHardLimits(written, discarded);
277	      if (limited.length === 0) throw new Error(`the writer returned no usable scene (${discarded.length} discarded)`);
278	
279	      // The arc closes on the stats scene. A flag follows the last validation scene of its session, or precedes the stats.
280	      const body = [...limited.filter((s) => s.type !== 'stats'), ...limited.filter((s) => s.type === 'stats')];
281	      const validations = body.filter((s) => s.type === 'terminal').reverse();
282	      const flags = flagged.map((claim) => ({
283	        scene: flagScene(claim),
284	        anchor: validations.find((s) => s.steps.some((step) => entries.get(step.entryId)?.sessionId === claim.sessionId))?.id,
285	      }));
286	      const loose = flags.filter((f) => f.anchor === undefined).map((f) => f.scene);
287	      const scenes: Scene[] = [{ id: 'title', type: 'title', lines: [], repo, windowLabel, sessionCount: ingest.sessions.length, commitCount: Number(facts['commits.count']) }];
288	      for (const scene of body) {
289	        if (scene.type === 'stats') scenes.push(...loose.splice(0));
290	        scenes.push(scene, ...flags.filter((f) => f.anchor === scene.id).map((f) => f.scene));
291	      }
292	      scenes.push(...loose, { id: 'end', type: 'end', lines: [], repo, verified: verify.counts.verified, flagged: verify.counts.contradicted + verify.counts.stale, unverified: verify.counts.unverifiable });
293	
294	      const storyboard = Storyboard.parse({ runId: ctx.run.id, repo, targetSec: TARGET_SEC, facts, scenes });
295	      ctx.log(`${limited.length} written scenes, ${flags.length} flag scenes, ${discarded.length} pieces of writer output discarded`);
296	      return { artifact: { storyboard, discarded } };
297	    },
298	  };
299	}
