301	/** What the writer sees of one beat: the prompts, the agent's messages and the shell runs in its ranges, and its patches. */
302	function beatMaterial(beat: Beat, ingest: IngestArtifact, sessions: Map<string, Session>): WriterMaterial['beats'][number] {
303	  const inRanges = beat.entryRanges.flatMap((range) => {
304	    const session = sessions.get(range.sessionId);
305	    if (!session) return [];
306	    const shell = new Set(session.entries.filter((e) => e.kind === 'tool_call' && e.command !== undefined).map((e) => e.toolUseId));
307	    return session.entries
308	      .slice(Math.max(0, range.from), range.to + 1)
309	      .filter((e) => e.kind === 'user' || e.kind === 'assistant' || (e.toolUseId !== undefined && shell.has(e.toolUseId)));
310	  });
311	  const shown = inRanges.length <= MATERIAL.entries ? inRanges : [...inRanges.slice(0, MATERIAL.entriesFromStart), ...inRanges.slice(MATERIAL.entriesFromStart - MATERIAL.entries)];
312	
313	  const view = (e: Entry) => ({
314	    id: e.id,
315	    kind: e.kind,
316	    text: e.kind === 'tool_result' ? tail(e.text, MATERIAL.entryChars) : cut(e.text, MATERIAL.entryChars),
317	    command: e.kind === 'tool_call' && e.command !== undefined ? cut(flat(e.command), ON_SCREEN.command) : undefined,
318	    errored: e.kind === 'tool_result' ? (e.isError ?? false) : undefined,
319	  });
320	  const patches = beat.commits
321	    .flatMap((sha) => Object.entries(ingest.diffs).filter(([key]) => key.startsWith(`${sha}:`)).map(([key, patch]) => ({ sha, path: key.slice(sha.length + 1), patch })))
322	    .slice(0, MATERIAL.patches)
323	    .map((p) => ({ sha: p.sha, path: p.path, ...patchCounts(p.patch), patch: cut(p.patch, MATERIAL.patchChars) }));
324	
325	  return { kind: beat.kind, title: beat.title, summary: beat.summary, entries: shown.map(view), patches };
326	}
