1	export type CommandClass = 'test' | 'build' | 'typecheck' | 'lint' | 'other';
2	
3	const PM = '(?:npm|pnpm|yarn|bun)';
4	
5	const TEST_PATTERNS = [
6	  /\bvitest\b/,
7	  /\bjest\b/,
8	  /\bpytest\b/,
9	  /\bmocha\b/,
10	  /\bplaywright\s+test\b/,
11	  /\bgo\s+test\b/,
12	  /\bcargo\s+test\b/,
13	  /\bdotnet\s+test\b/,
14	  /\brspec\b/,
15	  /\bphpunit\b/,
16	  /\bpython\s+-m\s+unittest\b/,
17	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?test\\b`),
18	  /\bmake\s+test\b/,
19	];
20	
21	const TYPECHECK_PATTERNS = [
22	  /\btsc\b/,
23	  /\bmypy\b/,
24	  /\bpyright\b/,
25	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?type-?check\\b`),
26	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?check-types\\b`),
27	];
28	
29	const LINT_PATTERNS = [
30	  /\beslint\b/,
31	  /\bbiome\b/,
32	  /\bruff\b/,
33	  /\bflake8\b/,
34	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?lint\\b`),
35	];
36	
37	const BUILD_PATTERNS = [
38	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?build\\b`),
39	  /\bnext\s+build\b/,
40	  /\bvite\s+build\b/,
41	  /\bcargo\s+build\b/,
42	  /\bgo\s+build\b/,
43	  /\bmake\b/,
44	];
45	
46	const ORDER: [CommandClass, RegExp[]][] = [
47	  ['test', TEST_PATTERNS],
48	  ['typecheck', TYPECHECK_PATTERNS],
49	  ['lint', LINT_PATTERNS],
50	  ['build', BUILD_PATTERNS],
51	];
52	
53	function classifyPart(part: string): CommandClass {
54	  for (const [cls, patterns] of ORDER) {
55	    if (patterns.some((re) => re.test(part))) return cls;
56	  }
57	  return 'other';
58	}
59	
60	export function classifyCommand(command: string): CommandClass {
61	  const parts = command.split(/&&|\|\||[;|]/).map((p) => p.trim());
62	  const classes = new Set(parts.map(classifyPart));
63	  for (const [cls] of ORDER) {
64	    if (classes.has(cls)) return cls;
65	  }
66	  return 'other';
67	}
