1	import type { Claim, Session } from '@dailies/core';
2	import { collectRuns, verifyClaim } from '@dailies/verify';
3	import { claimAnchor, isEvidencingRun, mutateRun, syntheticClaim } from './synthetic';
4	
5	type Verdict = NonNullable<Claim['verdict']>;
6	
7	export interface MutationCase {
8	  repo: string;
9	  sessionId: string;
10	  command: string;
11	  original: 'pass' | 'fail';
12	  verdictBefore: Verdict;
13	  verdictAfter: Verdict;
14	  flipped: boolean;
15	}
16	
17	const NOT_EVIDENCING_REASON = 'not the last run before the next message';
18	
19	export function runMutationBenchmark(sessions: { repo: string; session: Session }[]): {
20	  cases: MutationCase[];
21	  recognised: number;
22	  unknown: number;
23	  flipRate: number;
24	  version: 2;
25	  eligible: number;
26	  ineligible: number;
27	  ineligibleReasons: Record<string, number>;
28	} {
29	  const cases: MutationCase[] = [];
30	  let recognised = 0;
31	  let unknown = 0;
32	  let eligible = 0;
33	  const ineligibleReasons: Record<string, number> = {};
34	
35	  const bumpIneligible = (reason: string) => {
36	    ineligibleReasons[reason] = (ineligibleReasons[reason] ?? 0) + 1;
37	  };
38	
39	  for (const { repo, session } of sessions) {
40	    for (const run of collectRuns(session)) {
41	      if (run.outcome === 'unknown') {
42	        unknown += 1;
43	        continue;
44	      }
45	      recognised += 1;
46	      const original = run.outcome;
47	
48	      const { gap } = claimAnchor(session, run);
49	      if (gap) {
50	        bumpIneligible(gap);
51	        continue;
52	      }
53	
54	      const before = syntheticClaim(session, run)!;
55	      if (!isEvidencingRun(session, run, before)) {
56	        bumpIneligible(NOT_EVIDENCING_REASON);
57	        continue;
58	      }
59	      eligible += 1;
60	
61	      const verdictBefore = verifyClaim(before, session).verdict as Verdict;
62	      const mutated = mutateRun(session, run, original === 'pass' ? 'fail' : 'pass');
63	      const verdictAfter = verifyClaim(before, mutated).verdict as Verdict;
64	
65	      const expectedBefore: Verdict = original === 'pass' ? 'verified' : 'contradicted';
66	      const expectedAfter: Verdict = original === 'pass' ? 'contradicted' : 'verified';
67	
68	      cases.push({
69	        repo,
70	        sessionId: session.id,
71	        command: run.command,
72	        original,
73	        verdictBefore,
74	        verdictAfter,
75	        flipped: verdictBefore === expectedBefore && verdictAfter === expectedAfter,
76	      });
77	    }
78	  }
79	
80	  const flipRate = cases.length === 0 ? 0 : cases.filter((c) => c.flipped).length / cases.length;
81	  const ineligible = Object.values(ineligibleReasons).reduce((a, b) => a + b, 0);
82	  return { cases, recognised, unknown, flipRate, version: 2, eligible, ineligible, ineligibleReasons };
83	}
