5	const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit']);
6	
7	function entryIndex(session: Session, entryId: string | null): number | null {
8	  if (entryId === null) return null;
9	  return session.entries.find((e) => e.id === entryId)?.index ?? null;
10	}
11	
12	export type ClaimGapReason = 'no following assistant entry' | 'a source edit in between';
13	
14	/** The next assistant entry after the run's result, and why `syntheticClaim` would decline to
15	 * anchor a claim there (null when it would succeed). Shared so a caller that needs to know why a
16	 * run was skipped doesn't re-derive the anchor logic. */
17	export function claimAnchor(session: Session, run: ToolRun): { assistant: Entry | undefined; gap: ClaimGapReason | null } {
18	  const afterIndex = entryIndex(session, run.resultEntryId) ?? run.index;
19	  const assistant = session.entries.find((e) => e.kind === 'assistant' && e.index > afterIndex);
20	  if (!assistant) return { assistant: undefined, gap: 'no following assistant entry' };
21	
22	  const edit = session.entries.find(
23	    (e) =>
24	      e.kind === 'tool_call' &&
25	      e.index > afterIndex &&
26	      e.index < assistant.index &&
27	      e.toolName !== undefined &&
28	      EDIT_TOOLS.has(e.toolName) &&
29	      e.filePath !== undefined &&
30	      !e.filePath.endsWith('.md'),
31	  );
32	  if (edit) return { assistant, gap: 'a source edit in between' };
33	  return { assistant, gap: null };
34	}
35	
36	/** Builds a tests_pass/build_passes claim anchored to the first assistant entry after the run's
37	 * result, or null when there is none or a non-markdown source edit sits between them. */
38	export function syntheticClaim(session: Session, run: ToolRun): Claim | null {
39	  const { assistant, gap } = claimAnchor(session, run);
40	  if (gap || !assistant) return null;
41	
42	  return {
43	    id: `synthetic:${run.callEntryId}`,
44	    sessionId: session.id,
45	    entryId: assistant.id,
46	    quote: assistant.text.slice(0, 80),
47	    kind: run.cls === 'test' ? 'tests_pass' : 'build_passes',
48	    evidence: [],
49	  };
50	}
51	
52	const CLASSES_FOR_CLAIM_KIND: Partial<Record<Claim['kind'], CommandClass[]>> = {
53	  tests_pass: ['test'],
54	  build_passes: ['build', 'typecheck', 'lint'],
55	};
56	
57	/** True only when `run` is the last run of the claim's class group with an index before the
58	 * claim's entry — the run `verifyClaim`'s lastRunVerdict will actually rest the verdict on.
59	 * Several runs of the same class often precede one assistant message; mutating any run but this
60	 * one cannot change the verdict, since verifyClaim always recomputes "the last run" itself. */
61	export function isEvidencingRun(session: Session, run: ToolRun, claim: Claim): boolean {
62	  const claimEntry = session.entries.find((e) => e.id === claim.entryId);
63	  if (!claimEntry) return false;
64	
65	  const classes = CLASSES_FOR_CLAIM_KIND[claim.kind];
66	  if (!classes) return false;
67	
68	  const matching = collectRuns(session).filter((r) => classes.includes(r.cls) && r.index < claimEntry.index);
69	  const last = matching[matching.length - 1];
70	  return last !== undefined && last.callEntryId === run.callEntryId;
71	}
72	
73	function canonicalOpposite(run: ToolRun, to: 'pass' | 'fail'): { text: string; isError: boolean } {
74	  if (run.cls === 'test') {
75	    return to === 'fail'
76	      ? { text: 'Tests  3 failed | 11 passed', isError: true }
77	      : { text: 'Tests  14 passed (14)', isError: false };
78	  }
79	  if (run.cls === 'typecheck') {
80	    return to === 'fail' ? { text: 'error TS2322: mutated', isError: true } : { text: '', isError: false };
81	  }
82	  // build/lint share parseLintOrBuildOutcome, whose fail marker is a leading count, not "error TSxxxx".
83	  return to === 'fail' ? { text: '3 errors', isError: true } : { text: '', isError: false };
84	}
85	
86	/** Returns a copy of `session` with the targeted run's recorded result replaced by a canonical
87	 * opposite outcome; the original session and its other runs are untouched. */
88	export function mutateRun(session: Session, run: ToolRun, to: 'pass' | 'fail'): Session {
89	  const copy = structuredClone(session);
90	  const result = copy.entries.find((e) => e.id === run.resultEntryId);
91	  if (!result) return copy;
92	  const { text, isError } = canonicalOpposite(run, to);
93	  result.text = text;
94	  result.isError = isError;
95	  return copy;
96	}
